base=u10.base
R=Path(__file__).resolve().parents[2];A1=R/'reading/french/a1/passages.jsonl';A2=R/'reading/french/a2/passages.jsonl';B1=R/'reading/french/b1/passages.jsonl';B2=R/'reading/french/b2/passages.jsonl';C1=R/'reading/french/c1/passages.jsonl';C2=R/'reading/french/c2/passages.jsonl';SCHEMA=R/'reading/schema/passage.schema.json';READY=R/'reading/audit/french_c2_readiness.json';SEL=R/'reading/audit/french_c2_unit01_target_selection.json';C1LOCK=R/'reading/audit/french_c1_unit10_frontier_lock.json';LEX1=R/'french_top1000.csv';LEX3=R/'french_top3000.csv';PAIR='fr-c2-u01-intention-structure-viewpoints'
USE={
'réel':'« Réel » qualifie ici ce qui est posé comme indépendant d’une description particulière; la difficulté est précisément de déterminer quel test permet de distinguer cette indépendance d’un accord simplement stable entre observateurs.',
'réalité':'La « réalité » n’est pas employée comme mot magique qui clôt le débat : elle désigne l’ensemble de ce à quoi nos descriptions prétendent répondre, y compris lorsque plusieurs descriptions compatibles découpent cet ensemble différemment.',
'terme':'Un « terme » est à la fois une unité linguistique et un outil de découpage conceptuel; changer le terme peut ne rien changer au monde, mais peut modifier les distinctions que l’argument rend visibles.',
'pensée':'La « pensée » désigne ici une activité de conceptualisation et d’inférence; le texte distingue son contenu, son expression linguistique et les conditions extérieures auxquelles elle prétend correspondre.',
'identité':'L’« identité » devient un problème lorsqu’on demande selon quel critère une chose, une personne ou un concept reste le même à travers le changement; la réponse varie selon la propriété que l’enquête juge pertinente.',
'nécessaire':'« Nécessaire » signifie que l’absence d’une condition exclurait le résultat envisagé; le passage insiste sur le fait qu’une condition nécessaire peut rester très loin d’être suffisante.',
'importance':'L’« importance » d’un facteur dépend de la question : un élément peut être causalement indispensable, statistiquement faible et pourtant décisif pour une classification ou une décision particulière.',
'dépendre':'« Dépendre » exprime une relation asymétrique qu’il faut spécifier : dépendance logique, causale, définitionnelle ou pratique n’obéissent pas aux mêmes critères de preuve.',
'contraire':'Le « contraire » d’une proposition n’est pas toujours son simple opposé lexical; en logique argumentative, nier une thèse, affirmer son contraire et proposer une alternative incompatible sont des opérations différentes.',
'faible':'« Faible » qualifie ici un degré relatif — probabilité, effet, justification ou dépendance — et n’a de sens précis qu’avec une échelle ou un contraste explicite.',
'juger':'« Juger » signifie attribuer une propriété, une responsabilité ou une valeur à partir de raisons; le passage sépare le verdict pratique de la simple réaction et de la description factuelle.',
'justice':'La « justice » est traitée comme un ensemble de critères concurrents — égalité, proportion, procédure, réparation — dont la priorité doit être argumentée plutôt que présumée.',
'intention':'L’« intention » relie une action à une représentation de ce que l’agent cherchait à faire; elle ne se lit pas directement dans le résultat et doit être inférée à partir d’indices faillibles.',
'considérer':'« Considérer » un fait signifie ici lui accorder une place dans le raisonnement; cela ne fixe ni son poids ni la conclusion qu’il devrait imposer.',
'prétendre':'« Prétendre » marque une revendication de vérité ou de droit qui demande encore justification; le verbe permet de conserver une distance entre ce qu’une voix affirme et ce que le texte accepte.',
'représenter':'« Représenter » peut signifier décrire, rendre présent par un symbole ou agir au nom d’autrui; le passage exploite cette polysémie pour montrer qu’une même forme peut engager des critères de fidélité différents.',
'lien':'Un « lien » indique une relation sans en préciser la nature; l’analyse exige de dire si ce lien est causal, logique, social, conventionnel ou simplement corrélationnel.',
'lier':'« Lier » deux propositions consiste à construire une relation argumentative; la présence successive de deux idées ne suffit pas à montrer que l’une soutient, explique ou implique l’autre.',
'identifier':'« Identifier » revient à fixer un critère de reconnaissance; ce critère peut fonctionner pour une tâche donnée tout en échouant lorsqu’on change d’échelle ou de contexte.',
'principal':'« Principal » désigne ce qui reçoit la priorité dans une explication; le texte demande si cette priorité vient de la force causale, de la fréquence, de la valeur ou simplement de l’ordre narratif.',
'certainement':'« Certainement » est étudié comme marqueur épistémique : selon le contexte, il peut exprimer une quasi-certitude, une forte confiance ou une concession rhétorique plus fragile qu’elle n’en a l’air.',
'soutenir':'« Soutenir » une thèse exige davantage que la rendre compatible avec les faits; les éléments invoqués doivent augmenter sa crédibilité relativement à des alternatives pertinentes.',
'confirmer':'« Confirmer » signifie renforcer une hypothèse déjà formulée; une observation qui était garantie par plusieurs hypothèses rivales possède un pouvoir confirmatoire limité.',
'résoudre':'« Résoudre » un problème conceptuel peut vouloir dire dissiper une contradiction, choisir une définition ou montrer que la question était mal posée; ces succès ne sont pas interchangeables.',
'utile':'« Utile » introduit un critère pragmatique qui peut diverger de la vérité, de l’élégance ou de la profondeur explicative; une distinction peut être utile sans être la seule manière légitime de décrire le phénomène.'
}
EXTRA=[
"Le passage construit ensuite un contre-exemple minimal. Au lieu d’accumuler des cas favorables, il cherche une situation où deux définitions qui semblaient équivalentes produisent des classifications différentes. Ce cas frontière ne décide pas automatiquement laquelle est meilleure; il révèle la propriété implicite que chacune traitait comme essentielle.",
"Une deuxième étape distingue le niveau métaphysique du niveau épistémique. Ce qui existe, ce que nous pouvons savoir de ce qui existe et le vocabulaire avec lequel nous formulons cette connaissance sont liés, mais une difficulté dans l’un de ces niveaux ne doit pas être déplacée silencieusement vers les deux autres.",
"Le meilleur argument rival est reformulé sans caricature. Le texte indique ce qu’il explique mieux, ce qu’il doit supposer et le type de cas qui l’affaiblirait. Cette reconstruction empêche une conclusion de paraître nécessaire simplement parce qu’aucune alternative sérieuse n’a été autorisée à entrer dans le raisonnement.",
"L’analyse teste enfin la portée de la distinction. Une opposition peut être décisive dans un problème précis et devenir inutile ailleurs; inversement, une catégorie grossière peut rester pragmatiquement efficace même si elle ne capture pas toutes les différences ontologiques que le philosophe souhaiterait conserver.",
"La conclusion annonce une règle de révision. Si un nouveau cas oblige à multiplier les exceptions ad hoc, si une distinction ne modifie aucune inférence ou si une alternative explique les mêmes contrastes avec moins de présupposés, la structure conceptuelle doit être reformulée plutôt que protégée par définition."
]
def h(p):return subprocess.check_output(['git','hash-object',str(p)],text=True).strip()
def load(p):return [json.loads(x) for x in p.read_text(encoding='utf-8').splitlines() if x.strip()]
def readdeck(path):
 out={}
 with path.open(encoding='utf-8',newline='') as f:
  for row in csv.DictReader(f):
   form=(row.get('Front') or '').strip();b=row.get('Back') or '';mr=re.search(r'Rank:\s*(\d+)',b);mm=re.search(r'Meaning:\s*(.+)',b);mp=re.search(r'Part of speech:\s*(.+)',b)
   if form and mr:out[form]={'rank':int(mr.group(1)),'sense':mm.group(1).strip() if mm else '', 'pos':mp.group(1).strip() if mp else '', 'source':path.name}
 return out
def deck():return {**readdeck(LEX1),**readdeck(LEX3)}
def nt(f,text,D):
 s=D[f];n=base.cnt(text,f)
 if n<1:raise AssertionError(f'{f}: no exact C2 exposure')
 return {'id':base.tid(s['rank']),'form':f,'lemma':f,'intended_sense':s['sense'],'part_of_speech':s['pos'],'register':'contemporary standard / advanced analytical','variety':None,'context_strategy':['contrast','category_relation','restatement'],'first_introduced':True,'exposures_in_text':n,'source_lexicon':s['source'],'source_rank':s['rank'],'beyond_base':True}
def fit(ps,lo,hi):
 p=list(ps);t='\n\n'.join(p);i=0
 while len(t.split())<lo and i<len(EXTRA):p[-1]+=' '+EXTRA[i];i+=1;t='\n\n'.join(p)
 if not lo<=len(t.split())<=hi:raise AssertionError(f'C2 Unit01 word band {len(t.split())} not {lo}-{hi}')
 return p,t
def bridge(fs):return 'Révision C1 intégrée : '+', '.join(f'« {x} »' for x in fs)+'. Le texte les réemploie comme outils de comparaison sans les présenter comme nouveau lexique.'
def qitems(s,forms):
 core=[('main_claim',s['qclaim'],s['aclaim'],[forms[0]]),('ambiguity_resolution',s['qamb'],s['aamb'],[forms[1]]),('assumption',s['qassume'],s['aassume'],[forms[2]]),('rhetorical_function',s['qrhet'],s['arhet'],[forms[3]]),('stance',s['qstance'],s['astance'],[forms[4]])]
 return core+[('vocabulary_in_context',f'Quelle distinction conceptuelle « {f} » permet-il ici ?',USE[f],[f]) for f in forms]
def mk(s,forms,reviews,prior,D,lo,hi,theme):
 ps=list(s['paras']);ps[1]+=' '+' '.join(USE[f] for f in forms);ps[2]+=' '+bridge(reviews);ps,text=fit(ps,lo,hi);P=base.prior(prior);new=[nt(f,text,D) for f in forms];rev=[base.rev(f,P) for f in reviews];ids={t['form']:t['id'] for t in new+rev};q,a=base.qa(qitems(s,forms),ids)
 return {'id':s['id'],'language':'fr','cefr':'C2','unit':1,'sequence':s['seq'],'revision':1,'title':s['title'],'passage_type':s['ptype'],'genre':s['genre'],'domains':['educational','public'],'topics':[theme]+s['topics'],'text':text,'word_count':len(text.split()),'sentence_count':max(1,len(re.findall(r'[.!?](?:[»”\"])?',text))),'estimated_known_token_coverage':0,'new_lexical_targets':new,'review_lexical_targets':rev,'grammar_targets':[{'id':s['id']+'-g1','role':'integration','description':'scope modality, negation, counterfactuals and metalinguistic distinctions at discourse level'}],'discourse_targets':[{'id':s['id']+'-d1','role':'integration','description':'reconstruct distinction, counterexample, rival interpretation, scope and revision criterion'}],'questions':q,'answer_key':a,'speed_training':{'timed':False,'benchmark_eligible':False,'comprehension_gate':0.8,'new_word_policy':'controlled','notes':'C2 Unit01 calibration; discourse load prioritized over lexical quota.'},'quality':{'status':'draft','schema_check':'pending','linguistic_review':'pending','pedagogical_review':'pending','answer_key_check':'pending','coverage_check':'pending','fact_check':'not_required','notes':['C2 Unit01 calibration from validated top-3000 continuation.']},'paired_text_group':s.get('pair'),'prerequisites':['French C1 generation-integrity PASS'],'difficulty_notes_internal':'C2 conceptual distinction, ambiguity, counterexample and argument reconstruction.','reader_tags':['unit_role:'+s['ptype'],'calibration','french_c2_u01']}
def specs():return [
 {'id':'fr-c2-u01-p01','seq':1,'ptype':'instructional','genre':'argumentative essay','topics':['reality','language','identity'],'title':'Le réel n’est pas simplement ce qu’un vocabulaire découpe','paras':["Un débat conceptuel fictif oppose deux descriptions parfaitement compatibles avec les mêmes observations. La première classe un objet selon sa composition matérielle; la seconde selon sa fonction dans une pratique. Rien dans les données immédiates n’oblige à choisir une seule description. Le problème surgit lorsque l’une des deux classifications est présentée comme révélant ce que l’objet est « vraiment », comme si l’autre ne faisait que masquer sa nature.","L’essai commence par distinguer le monde auquel les descriptions répondent des critères par lesquels elles isolent une unité pertinente. Une carte et un inventaire peuvent porter sur le même territoire sans découper les mêmes objets. Cette pluralité ne prouve ni que toutes les descriptions se valent, ni que l’une doit correspondre à une structure unique déjà étiquetée indépendamment de toute enquête.","Le contre-exemple porte sur un objet dont la matière reste constante alors que la fonction change. Si l’identité dépend uniquement de la matière, on obtient une réponse; si elle dépend de la continuité fonctionnelle, on en obtient une autre. Le cas ne tranche pas par lui-même : il rend visible la propriété que chaque théorie avait silencieusement privilégiée.","Une lecture rivale soutient qu’il doit néanmoins exister un fait déterminé sur ce que l’objet est. L’essai répond en distinguant l’existence du phénomène et la granularité de sa description. Dire que les critères de classification sont partiellement liés à nos questions ne revient pas à dire que les réponses sont arbitraires : certaines classifications prédisent, expliquent ou coordonnent mieux que d’autres.","La conclusion adopte un réalisme modeste. Les descriptions sont contraintes par ce qui résiste à nos attentes, mais plusieurs schèmes peuvent capturer des relations réelles à des fins différentes. Le travail philosophique consiste alors à annoncer les critères d’identité, les inférences qu’ils autorisent et les cas qui obligeraient à les réviser."],'qclaim':'Quelle thèse centrale organise l’essai ?','aclaim':'Un monde indépendant de nos descriptions peut contraindre plusieurs classifications légitimes dont les critères d’identité doivent être explicités.','qamb':'Quelle ambiguïté du mot « réalité » l’essai cherche-t-il à éviter ?','aamb':'Confondre l’existence indépendante du phénomène avec l’idée qu’une seule granularité de description serait imposée sans choix conceptuel.','qassume':'Que suppose le réalisme modeste défendu à la fin ?','aassume':'Que les descriptions peuvent être contraintes par le monde sans qu’une seule manière de découper tous les phénomènes soit nécessairement privilégiée.','qrhet':'Quel rôle joue le cas de l’objet dont la fonction change ?','arhet':'Il sert de contre-exemple discriminant qui rend visibles deux critères concurrents d’identité.','qstance':'Quelle position l’auteur adopte-t-il face au relativisme et au réalisme fort ?','astance':'Il refuse l’arbitraire relativiste mais aussi l’idée que toute bonne description doive reproduire une unique taxonomie indépendante des questions.'},
 {'id':'fr-c2-u01-p02','seq':2,'ptype':'reinforcement','genre':'counterexample','topics':['necessity','dependence','opposition'],'title':'Une condition nécessaire peut expliquer très peu','paras':["Une théorie fictive affirme qu’un phénomène social ne peut apparaître sans une certaine ressource. Plusieurs exemples confirment qu’en l’absence totale de cette ressource, le phénomène disparaît. L’auteur conclut alors que la ressource constitue l’explication principale. Le passage examine le saut entre nécessité et importance explicative.","Une condition peut être nécessaire tout en variant très peu dans les cas où le résultat varie énormément. L’oxygène est nécessaire à de nombreuses activités humaines, mais cette nécessité n’en fait pas l’explication principale de toutes leurs différences. Inversement, un facteur non nécessaire peut modifier fortement la probabilité ou la forme d’un résultat.","Le texte distingue dépendance logique, dépendance causale et dépendance décisionnelle. Dans la première, nier une prémisse rend une proposition incohérente; dans la deuxième, modifier une condition change le processus; dans la troisième, une différence devient pertinente parce qu’elle modifie ce qu’un agent doit choisir. Employer le même vocabulaire de dépendance sans préciser le niveau produit de fausses équivalences.","Un contreargument soutient qu’une condition nécessaire mérite forcément un statut explicatif privilégié puisqu’elle définit la possibilité même du phénomène. Le passage répond que la question explicative peut porter non sur la possibilité mais sur le contraste : pourquoi ce cas plutôt qu’un autre, pourquoi cette intensité plutôt qu’une autre ? Le facteur pertinent dépend alors du contraste à expliquer.","La conclusion propose un test : préciser la proposition contraire, retirer mentalement la condition, puis modifier les facteurs qui varient entre les cas. Une explication devient plus précise lorsqu’elle indique à quel type de dépendance elle prétend répondre et quelle intervention ou comparaison pourrait la distinguer d’une simple condition de fond."],'qclaim':'Quelle erreur conceptuelle le passage critique-t-il ?','aclaim':'Inférer qu’une condition est l’explication principale simplement parce qu’elle est nécessaire.','qamb':'Quels sens de « dépendre » doivent être séparés ?','aamb':'Au moins les dépendances logique, causale et décisionnelle.','qassume':'Pourquoi une explication doit-elle préciser le contraste étudié ?','aassume':'Parce que le facteur pertinent pour rendre un phénomène possible peut différer de celui qui explique ses variations entre cas.','qrhet':'Quel rôle joue l’exemple de l’oxygène ?','arhet':'Il montre par contre-exemple qu’une condition omniprésente et nécessaire peut avoir peu de pouvoir pour expliquer un contraste particulier.','qstance':'Quelle méthode l’auteur préfère-t-il ?','astance':'Spécifier le type de nécessité, le contraste explicatif et le test qui différencie une condition de fond d’un facteur explicatif.'},
 {'id':'fr-c2-u01-p03','seq':3,'ptype':'paired','genre':'argumentative essay','topics':['intention','responsibility','justice'],'title':'Perspective A : juger une action exige de reconstruire ce que l’agent faisait','pair':PAIR,'paras':["La première perspective soutient qu’une attribution de responsabilité devient conceptuellement instable si elle ignore entièrement l’intention. Deux personnes peuvent produire le même résultat matériel tout en agissant sous des descriptions différentes : l’une cherche le résultat, l’autre poursuit un but incompatible avec lui et l’obtient accidentellement. Traiter ces situations comme identiques efface une distinction que nos pratiques de jugement utilisent constamment.","L’argument ne prétend pas que l’intention soit directement observable. Elle est reconstruite à partir d’actions antérieures, de raisons données, de choix évités et de ce que l’agent pouvait raisonnablement anticiper. Cette inférence peut échouer; précisément pour cette raison, la perspective A insiste sur la différence entre preuve d’intention et simple projection psychologique.","Un premier contre-exemple vise les conséquences prévisibles non désirées. Une personne peut ne pas vouloir un dommage tout en l’acceptant comme coût de son projet. La perspective A répond que l’opposition entre intention et absence d’intention est trop grossière : objectif, moyen choisi, risque consciemment accepté et négligence doivent être distingués.","La perspective rivale objecte que les institutions doivent parfois juger des actes à partir de critères publics plutôt que d’états mentaux difficiles à vérifier. A l’admet partiellement, mais soutient que le choix des critères publics doit lui-même expliquer quelles différences de responsabilité il veut préserver. Sinon la facilité de preuve risque de devenir, sans argument, une théorie de la responsabilité.","La conclusion défend une architecture graduée. Le résultat matériel, la connaissance du risque, l’intention, les alternatives disponibles et la règle institutionnelle peuvent tous compter, mais leur poids doit être justifié. La justice n’est pas réduite à lire l’esprit; elle refuse simplement de considérer que la seule conséquence observable épuise ce qu’il y a à juger."],'qclaim':'Quelle thèse défend la perspective A ?','aclaim':'Des résultats matériels identiques peuvent engager des responsabilités différentes selon l’intention, la connaissance du risque et les alternatives de l’agent.','qamb':'Pourquoi l’opposition intention/absence d’intention est-elle jugée trop grossière ?','aamb':'Parce qu’elle confond objectif poursuivi, moyen choisi, risque accepté et négligence.','qassume':'Que suppose l’usage institutionnel de critères publics selon A ?','aassume':'Qu’on explique quelles distinctions de responsabilité ces critères cherchent à préserver plutôt que de prendre la facilité de preuve pour une théorie morale complète.','qrhet':'Quel rôle joue le cas des conséquences prévisibles mais non voulues ?','arhet':'Il force la position à raffiner son vocabulaire de l’intention au lieu d’utiliser une opposition binaire.','qstance':'Quelle conception de la justice apparaît ici ?','astance':'Une attribution de responsabilité graduée qui combine faits publics et reconstruction prudente des raisons et risques assumés.'},
 {'id':'fr-c2-u01-p04','seq':4,'ptype':'paired','genre':'critique','topics':['representation','public reasons','structure'],'title':'Perspective B : la responsabilité doit rester représentable dans des raisons publiques','pair':PAIR,'paras':["La seconde perspective ne nie pas que les intentions existent ni qu’elles puissent parfois être pertinentes. Elle conteste plutôt leur rôle de centre conceptuel. Une institution qui doit traiter des cas comparables a besoin de critères que les personnes concernées peuvent identifier, discuter et contester. Si la responsabilité dépend trop fortement d’une reconstruction psychologique inaccessible, la justification risque de devenir asymétrique : celui qui décide prétend connaître un état intérieur que l’autre ne peut réfuter.","B propose donc de distinguer représentation de l’agent et structure de l’action. Une règle peut tenir compte de ce qui était annoncé, des options effectivement disponibles, du risque objectivement accessible et de la cohérence entre raison donnée et comportement observé. Ces éléments ne révèlent pas une intériorité complète, mais ils créent un espace public de contestation.","Le meilleur contre-exemple est celui d’une règle parfaitement publique qui classe pourtant ensemble deux actes moralement très différents. B reconnaît cette difficulté. Il répond qu’un système public n’a pas à être conceptuellement aveugle : il peut ajouter des catégories de connaissance, de contrainte ou de finalité, à condition que ces catégories soient liées à des indices discutables plutôt qu’à une intuition invérifiable du décideur.","La perspective A objecte alors qu’une telle réponse réintroduit l’intention sous d’autres noms. B accepte le lien, mais refuse l’identité. Pour lui, la question principale n’est pas de reproduire exactement l’état mental, mais de construire des critères suffisamment proches des différences moralement pertinentes tout en restant publiquement justifiables et révisables.","La conclusion déplace le problème de la vérité psychologique vers la légitimité de la représentation. Une procédure peut être imparfaite tout en étant préférable si ses erreurs sont visibles, contestables et corrigibles. Le principal désaccord avec A porte donc sur la priorité : fidélité à l’état mental ou qualité publique des critères qui le représentent imparfaitement."],'qclaim':'Quelle priorité défend la perspective B ?','aclaim':'La responsabilité institutionnelle doit être formulée par des critères publics, contestables et révisables même s’ils représentent imparfaitement l’état mental.','qamb':'Quelle distinction B établit-il entre représentation et identité ?','aamb':'Un critère public peut représenter une différence psychologique pertinente sans être identique à l’état mental qu’il cherche à approximer.','qassume':'Pourquoi la contestabilité est-elle centrale ?','aassume':'Parce qu’une justification légitime doit pouvoir être examinée par les personnes auxquelles elle s’applique plutôt que dépendre d’une intuition inaccessible du décideur.','qrhet':'Quel rôle joue le contre-exemple d’une règle publique qui classe mal deux actes ?','arhet':'Il oblige B à admettre des catégories plus fines et montre que publicité seule ne suffit pas.','qstance':'Où se situe le désaccord principal avec A ?','astance':'B donne priorité à des critères publics corrigibles; A donne davantage de poids à la fidélité de la reconstruction intentionnelle.'},
 {'id':'fr-c2-u01-p05','seq':5,'ptype':'integration','genre':'critique','topics':['confirmation','argument closure','pragmatism'],'title':'Quand peut-on dire qu’un problème conceptuel est résolu ?','paras':["Un dernier essai examine une formule fréquente dans les débats : « cette observation confirme notre distinction ». L’auteur demande ce que confirmer veut dire lorsque plusieurs cadres conceptuels peuvent absorber le même cas. Une observation compatible avec une théorie n’est pas forcément discriminante; elle peut avoir été attendue par toutes les alternatives sérieuses.","Le texte distingue soutien, compatibilité et résolution. Une donnée soutient davantage une thèse lorsqu’elle était moins attendue sous une rivale pertinente. Une contradiction apparente peut être résolue en corrigeant une définition, mais cette correction ne montre pas nécessairement que la théorie entière est vraie. Enfin, une distinction peut être utile pour organiser la recherche sans avoir encore reçu un statut ontologique définitif.","Le passage analyse ensuite les adverbes de confiance. Dire qu’une conclusion est certainement correcte peut fonctionner comme résultat d’un argument, comme signal rhétorique de fermeture ou comme invitation à ne plus considérer des alternatives. Le lecteur C2 doit identifier cette fonction à partir de la structure argumentative, pas seulement de la force lexicale du mot.","Le meilleur contreargument soutient qu’une enquête ne peut jamais avancer si chaque conclusion reste ouverte. Le texte répond en distinguant fermeture locale et fermeture absolue. On peut résoudre une question opératoire — quelle définition employer dans cette étude, quel modèle tester ensuite — tout en conservant la possibilité qu’un autre contexte révèle une distinction plus fondamentale.","La conclusion propose trois critères de clôture provisoire : les alternatives principales ont été reconstruites loyalement; les contre-exemples connus ont reçu une réponse qui ne multiplie pas arbitrairement les exceptions; et la distinction retenue modifie réellement des inférences, prédictions ou décisions. Une solution conceptuelle est ainsi un point de stabilité argumenté, non une interdiction de penser autrement."],'qclaim':'Quelle distinction centrale organise la conclusion ?','aclaim':'Il faut distinguer compatibilité, soutien relatif et résolution provisoire d’un problème conceptuel.','qamb':'Pourquoi « certainement » peut-il être ambigu dans un argument ?','aamb':'Parce qu’il peut signaler un degré de confiance justifié ou fonctionner rhétoriquement comme fermeture prématurée du débat.','qassume':'Que suppose une clôture provisoire défendable ?','aassume':'Que les alternatives sérieuses et contre-exemples soient traités et que la distinction choisie ait des conséquences inférentielles réelles.','qrhet':'Quel rôle joue la distinction entre fermeture locale et absolue ?','arhet':'Elle permet d’agir ou de poursuivre une recherche sans prétendre que toute révision future est conceptuellement impossible.','qstance':'Quelle attitude l’auteur adopte-t-il face à la résolution philosophique ?','astance':'Il accepte des points de stabilité argumentés et utiles tout en refusant de confondre résolution opératoire et vérité finale irrévisable.'}]
def checkpoint(groups,D,lo,hi,theme,prior):
 forms=[f for k in ['p01','p02','p03','p04','p05'] for f in groups[k]];ps=["Le checkpoint C2 présente un débat fictif où trois auteurs semblent employer les mêmes mots — réalité, nécessité, responsabilité, représentation et confirmation — tout en défendant des thèses incompatibles. Le lecteur ne peut pas résoudre le désaccord en remplaçant chaque mot par une définition unique : il doit reconstruire le rôle que chaque distinction joue dans les inférences de chaque auteur.","La première tâche consiste à isoler les niveaux. Une affirmation porte sur ce qui existe, une autre sur ce qui peut être connu, une troisième sur les critères publics d’une décision. Les textes se contredisent parfois réellement et se croisent parfois sans répondre à la même question. Identifier cette différence évite les faux désaccords autant que les faux consensus.","La deuxième tâche construit des contre-exemples. Pour chaque distinction, le lecteur imagine un cas où deux critères jusque-là alignés se séparent : même matière mais fonction différente, même conséquence mais intention différente, même preuve mais seuil décisionnel différent. Le cas frontière révèle ce que chaque théorie traite comme principal.","La troisième tâche reconstruit les meilleures réponses rivales. Une position n’est pas évaluée à partir de sa formulation la plus faible; le lecteur doit montrer ce qu’elle explique mieux, quelle ambiguïté elle résout et quel prix conceptuel elle paie. Ce travail rend la comparaison cumulative plutôt que polémique.","La conclusion choisit une architecture provisoire : certaines distinctions sont maintenues, d’autres fusionnées, d’autres encore limitées à un domaine. Le lecteur annonce enfin une condition de révision. À C2, reconstruire la nuance signifie pouvoir dire non seulement quelle thèse paraît meilleure, mais exactement quel changement de cas, de niveau ou d’objectif ferait perdre cette supériorité." ];ps[1]+=' Révision cumulative : '+'; '.join(f'« {f} »' for f in forms)+'.';ps,text=fit(ps,lo,hi);P=base.prior(prior);rev=[base.rev(f,P) for f in forms];ids={t['form']:t['id'] for t in rev};items=[('main_claim','Quelle compétence générale le checkpoint exige-t-il ?','Reconstruire le rôle inférentiel de distinctions concurrentes avant de décider si les textes sont réellement en désaccord.',[forms[0]]),('ambiguity_resolution','Comment distinguer faux désaccord et contradiction réelle ?','En identifiant le niveau, la proposition précise et les conséquences inférentielles de chaque emploi.',[forms[1]]),('assumption','Que suppose un bon contre-exemple conceptuel ?','Qu’il sépare deux critères auparavant confondus sans modifier toutes les autres dimensions pertinentes du cas.',[forms[5]]),('rhetorical_function','Pourquoi reconstruire la meilleure version d’une position rivale ?','Pour éviter qu’une préférence apparaisse nécessaire seulement parce que l’alternative a été affaiblie.',[forms[10]]),('stance','Quelle posture finale caractérise la calibration C2 ?','Une comparaison conceptuelle précise, charitable envers les alternatives, attentive aux niveaux et explicitement révisable.',[forms[15]]),('cross_text_synthesis','Quel compromis relie les perspectives A et B sur la responsabilité ?','Toutes deux veulent préserver des différences pertinentes de responsabilité; A privilégie la fidélité à l’intention reconstruite, B la contestabilité publique des critères qui la représentent.',[forms[12],forms[16]]),('register_style','Pourquoi un adverbe de certitude doit-il être interprété par sa fonction rhétorique ?','Parce que la même forme peut exprimer une confiance justifiée ou servir à fermer prématurément la discussion.',[forms[20]]),('inference','Que montre une distinction qui ne change aucune inférence ni décision ?','Qu’elle peut être verbalement nette mais conceptuellement peu productive dans le problème considéré.',[forms[23]]),('summary','Résume la méthode du checkpoint.','Séparer les niveaux, construire des cas discriminants, reconstruire les rivales, comparer leurs coûts et annoncer une condition de révision.',[forms[24]]),('synthesis','Quelle règle se transfère à un nouveau débat abstrait ?','Identifier ce que chaque distinction permet d’inférer, chercher un cas qui sépare les critères et ajuster la conclusion au niveau exact du désaccord.',[forms[4],forms[9],forms[19]])];q,a=base.qa(items,ids)
 return {'id':'fr-c2-u01-p06','language':'fr','cefr':'C2','unit':1,'sequence':6,'revision':1,'title':'Checkpoint : distinguer les niveaux, les critères et les vraies contradictions','passage_type':'checkpoint','genre':'counterexample','domains':['educational','public'],'topics':[theme,'C2 conceptual synthesis'],'text':text,'word_count':len(text.split()),'sentence_count':max(1,len(re.findall(r'[.!?](?:[»”\"])?',text))),'estimated_known_token_coverage':0,'new_lexical_targets':[],'review_lexical_targets':rev,'grammar_targets':[{'id':'fr-c2-u01-p06-g1','role':'integration','description':'integrate metalinguistic scope, modal force, negation and counterfactual qualification'}],'discourse_targets':[{'id':'fr-c2-u01-p06-d1','role':'integration','description':'synthesize conceptual levels, ambiguity, counterexample, rival interpretation and revision'}],'questions':q,'answer_key':a,'speed_training':{'timed':True,'benchmark_eligible':True,'comprehension_gate':0.8,'new_word_policy':'none','notes':'C2 Unit01 zero-new calibration checkpoint.'},'quality':{'status':'draft','schema_check':'pending','linguistic_review':'pending','pedagogical_review':'pending','answer_key_check':'pending','coverage_check':'pending','fact_check':'not_required','notes':['C2 Unit01 calibration checkpoint; no new lexical targets.']},'paired_text_group':None,'prerequisites':['French C2 Unit01 P01-P05'],'difficulty_notes_internal':'C2 conceptual ambiguity, level distinction and charitable argument reconstruction.','reader_tags':['unit_role:checkpoint','calibration','french_c2_u01']}
